#ifndef KERNEL_CONFIG_H
#define KERNEL_CONFIG_H

/* Single hub for build-time configuration. Values come from .config via
 * include/generated/autoconf.h (generated by scripts/genconfig.sh; see Kconfig
 * for the catalogue and defconfig/tinyconfig for presets). Tune by editing
 * .config — never the CONFIG_* below. */
#include <generated/autoconf.h>

/* IS_ENABLED(CONFIG_FOO): 1 when "CONFIG_FOO=y" (autoconf emits "#define
 * CONFIG_FOO 1"), 0 when unset/=n. Use for code that must still compile when a
 * feature is off; the Makefile separately drops the feature's sources. */
#define __ARG_PLACEHOLDER_1 0,
#define __take_second(a, b, ...) b
#define __is_set(val)        __is_set_(__ARG_PLACEHOLDER_##val)
#define __is_set_(arg)       __take_second(arg 1, 0)
#define IS_ENABLED(opt)      __is_set(opt)

/* Legacy spellings kept so existing consumers need no churn; the values now
 * flow from .config. New code may use CONFIG_* directly. */
#define SCHED_QUANTUM   CONFIG_SCHED_QUANTUM
#define KSTACK_SIZE     CONFIG_KSTACK_SIZE
#define DENTRY_MAX      CONFIG_DENTRY_MAX
#define FD_TABLE_INIT   CONFIG_FD_TABLE_INIT
#define PIPE_BUF_SIZE   CONFIG_PIPE_BUF_SIZE
#define CMDLINE_MAX     CONFIG_CMDLINE_MAX
#define FUTEX_SLOTS     CONFIG_FUTEX_SLOTS

#endif
